async function chopAndCraft() {
  const blocks = world.findBlocks({
    matching: ['oak_log', 'birch_log', 'spruce_log', 'jungle_log', 'acacia_log', 'dark_oak_log', 'mangrove_log', 'cherry_log'],
    maxDistance: 32,
    count: 4
  });
  if (blocks && blocks.length > 0) {
    for (const pos of blocks) {
      const block = world.getBlockAt(pos);
      if (block) {
        await dsl.safeDigBlock(block, { sneak: true });
      }
    }
    await dsl.pickupNearbyItems(16);
  }

  const woodTypes = ['oak_log', 'birch_log', 'spruce_log', 'jungle_log', 'acacia_log', 'dark_oak_log', 'mangrove_log', 'cherry_log'];
  let woodSource = null;
  for (const w of woodTypes) {
    if (world.hasItem(w)) {
      woodSource = w;
      break;
    }
  }
  if (woodSource) {
    const planks = woodSource.replace('_log', '_planks');
    await dsl.craftItem(planks, 2);
    await dsl.craftItem('stick', 4);
    await dsl.craftItem('crafting_table', 1);
  } else {
    dsl.chat('No wood found in inventory after chopping');
  }
}

